"use client"
import * as React from "react"
import { AnimatePresence, Reorder, motion, useMotionTemplate, useMotionValue, useReducedMotion, useSpring, useTransform } from "framer-motion"
import { File as FileIcon, FileArchive, FileImage, FileText, RotateCw, UploadCloud, X } from "lucide-react"
import { cn } from "@/lib/utils"

export interface FileDropPhysicsProps {
  /** Do the upload. Call `progress(0..100)` as it goes. Reject to show the error state. */
  onUpload: (file: File, progress: (percent: number) => void) => Promise<void>
  title?: string
  hint?: string
  /** Comma separated, same format as the input accept attribute. */
  accept?: string
  maxFiles?: number
  maxSizeMb?: number
  className?: string
}

type Status = "uploading" | "done" | "error"
interface Row { id: string; file: File; status: Status; progress: number; tilt: number; dx: number }

const PINK = "#ff8fb8"
const GRADIENT = "linear-gradient(120deg,var(--primary),#ff9bc0)"
const size = (n: number) => (n < 1024 ? `${n} B` : n < 1048576 ? `${(n / 1024).toFixed(0)} KB` : `${(n / 1048576).toFixed(1)} MB`)
const kindOf = (f: File) => (f.type.startsWith("image/") ? FileImage : f.type === "application/pdf" || f.type.startsWith("text/") ? FileText : /zip|rar|7z|tar/.test(f.type + f.name) ? FileArchive : FileIcon)

function Burst() {
  return (
    <span aria-hidden className="pointer-events-none absolute right-4 top-1/2 z-10">
      {Array.from({ length: 14 }).map((_, i) => {
        const a = (i / 14) * Math.PI * 2, r = 30 + ((i * 17) % 26)
        return <motion.span key={i} className="absolute -ml-1 -mt-1 size-2 rounded-full" style={{ background: i % 2 ? "var(--primary)" : PINK, boxShadow: `0 0 10px ${PINK}` }}
          initial={{ x: 0, y: 0, opacity: 1, scale: 1 }} animate={{ x: Math.cos(a) * r, y: Math.sin(a) * r, opacity: 0, scale: 0.2 }} transition={{ duration: 0.8, ease: "easeOut" }} />
      })}
    </span>
  )
}

function Ring({ value, status }: { value: number; status: Status }) {
  const reduce = useReducedMotion()
  const r = 14, c = 2 * Math.PI * r
  return (
    <span className="relative grid size-11 shrink-0 place-items-center" role="img" aria-label={status === "done" ? "Uploaded" : status === "error" ? "Failed" : `${Math.round(value)} percent`}>
      <svg viewBox="0 0 36 36" className="absolute inset-0 -rotate-90" aria-hidden>
        <circle cx="18" cy="18" r={r} fill="none" strokeWidth="3" className="stroke-border" />
        <motion.circle cx="18" cy="18" r={r} fill="none" strokeWidth="3" strokeLinecap="round" stroke={status === "error" ? "#e11d48" : "var(--primary)"} strokeDasharray={c} initial={false}
          animate={{ strokeDashoffset: c * (1 - (status === "done" ? 1 : value / 100)) }} transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 120, damping: 20 }} />
      </svg>
      {status === "done" ? (
        <svg viewBox="0 0 24 24" className="relative size-5 text-primary" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
          <motion.path d="M5 12.5l4.5 4.5L19 7.5" initial={{ pathLength: reduce ? 1 : 0 }} animate={{ pathLength: 1 }} transition={{ duration: 0.4, delay: 0.1 }} />
        </svg>
      ) : status === "error" ? <span className="relative text-sm font-bold text-red-600 dark:text-red-300">!</span> : <span className="relative text-[11px] font-semibold tabular-nums">{Math.round(value)}</span>}
    </span>
  )
}

export function FileDropPhysics({ onUpload, title = "Upload files", hint = "Drop them here, or press the button.", accept, maxFiles = 6, maxSizeMb = 25, className }: FileDropPhysicsProps) {
  const reduce = useReducedMotion()
  const input = React.useRef<HTMLInputElement>(null)
  const [rows, setRows] = React.useState<Row[]>([])
  const [over, setOver] = React.useState(false)
  const [note, setNote] = React.useState("")
  const alive = React.useRef(true)
  React.useEffect(() => { alive.current = true; return () => { alive.current = false } }, [])

  const mx = useMotionValue(0.5), my = useMotionValue(0.5)
  const rx = useSpring(useTransform(my, [0, 1], [3, -3]), { stiffness: 120, damping: 18 }), ry = useSpring(useTransform(mx, [0, 1], [-4, 4]), { stiffness: 120, damping: 18 })
  const px = useMotionValue(-300), py = useMotionValue(-300)
  const glow = useMotionTemplate`radial-gradient(260px circle at ${px}px ${py}px, color-mix(in oklab, var(--primary) 16%, transparent), transparent 70%)`

  const patch = (id: string, p: Partial<Row>) => setRows((r) => r.map((x) => (x.id === id ? { ...x, ...p } : x)))
  const start = async (row: Row) => {
    patch(row.id, { status: "uploading", progress: 0 })
    try {
      await onUpload(row.file, (n) => alive.current && patch(row.id, { progress: Math.max(0, Math.min(100, n)) }))
      if (alive.current) patch(row.id, { status: "done", progress: 100 })
    } catch { if (alive.current) patch(row.id, { status: "error" }) }
  }
  const add = (list: FileList | File[] | null) => {
    if (!list) return
    const files = Array.from(list)
    const okType = (f: File) => !accept || accept.split(",").some((a) => { a = a.trim(); return a.startsWith(".") ? f.name.toLowerCase().endsWith(a) : a.endsWith("/*") ? f.type.startsWith(a.slice(0, -1)) : f.type === a })
    const good = files.filter((f) => f.size <= maxSizeMb * 1048576 && okType(f))
    const room = Math.max(0, maxFiles - rows.length)
    const take = good.slice(0, room)
    const msgs = [files.length - good.length ? `${files.length - good.length} skipped (type or over ${maxSizeMb} MB)` : "", good.length > take.length ? `only ${maxFiles} files at a time` : ""].filter(Boolean)
    setNote(msgs.join(", "))
    const made = take.map((file, i): Row => ({ id: `${file.name}-${file.size}-${Math.random().toString(36).slice(2, 7)}`, file, status: "uploading", progress: 0, tilt: (Math.random() - 0.5) * 3, dx: (Math.random() - 0.5) * 12 + (i % 2 ? 4 : -4) }))
    setRows((r) => [...r, ...made])
    made.forEach((m, i) => setTimeout(() => start(m), 500 + i * 160))
  }
  const doneCount = rows.filter((r) => r.status === "done").length
  const total = rows.length ? rows.reduce((a, r) => a + (r.status === "done" ? 100 : r.progress), 0) / rows.length : 0
  const spring = reduce ? { duration: 0.01 } : { type: "spring" as const, stiffness: 190, damping: 11, mass: 1.05 }

  return (
    <div className={cn("relative w-full max-w-md", className)} style={{ perspective: 1100 }}>
      <motion.div aria-hidden className="pointer-events-none absolute -inset-3 rounded-[2rem] bg-[conic-gradient(from_40deg,var(--primary),#ff9bc0,#8b8fa3,var(--primary))] blur-2xl"
        animate={reduce ? { opacity: 0.2 } : { opacity: over ? 0.6 : [0.15, 0.35, 0.15] }} transition={{ duration: over ? 0.3 : 6, repeat: over ? 0 : Infinity, ease: "easeInOut" }} />
      <motion.section aria-label={title}
        onPointerMove={(e) => { const b = e.currentTarget.getBoundingClientRect(); mx.set((e.clientX - b.left) / b.width); my.set((e.clientY - b.top) / b.height); px.set(e.clientX - b.left); py.set(e.clientY - b.top) }}
        onPointerLeave={() => { mx.set(0.5); my.set(0.5) }}
        onDragOver={(e) => { e.preventDefault(); setOver(true) }} onDragLeave={(e) => { if (e.currentTarget === e.target) setOver(false) }} onDrop={(e) => { e.preventDefault(); setOver(false); add(e.dataTransfer.files) }}
        style={{ rotateX: reduce ? 0 : rx, rotateY: reduce ? 0 : ry, transformStyle: "preserve-3d" }}
        initial={{ opacity: 0, y: reduce ? 0 : 24 }} animate={{ opacity: 1, y: 0 }} transition={{ type: "spring", stiffness: 140, damping: 18 }}
        className="relative rounded-2xl border border-border bg-card p-5 text-foreground shadow-[0_40px_70px_-35px_color-mix(in_oklab,var(--primary)_55%,transparent)]">
        {!reduce && <motion.div aria-hidden className="pointer-events-none absolute inset-0 rounded-2xl" style={{ background: glow }} />}
        <header className="relative flex items-baseline justify-between" style={{ transform: "translateZ(20px)" }}>
          <h2 className="text-lg font-semibold tracking-tight">{title}</h2>
          <p aria-live="polite" className="text-xs tabular-nums text-muted-foreground">{rows.length ? `${doneCount} of ${rows.length} done` : `Up to ${maxFiles} files`}</p>
        </header>

        {/* drop target */}
        <motion.button type="button" onClick={() => input.current?.click()} aria-label="Choose files to upload"
          animate={{ scale: over && !reduce ? 1.04 : 1, borderRadius: over && !reduce ? 36 : 18 }} whileHover={reduce ? undefined : { scale: 1.015 }} whileTap={reduce ? undefined : { scale: 0.97 }} transition={{ type: "spring", stiffness: 300, damping: 14 }}
          className={cn("relative mt-4 grid min-h-36 w-full place-items-center overflow-hidden border-2 border-dashed px-4 py-6 text-center outline-none transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring", over ? "border-primary bg-primary/10" : "border-border bg-muted/50 hover:border-primary/60")}
          style={{ transform: "translateZ(14px)" }}>
          {!reduce && [0, 1, 2].map((i) => (
            <motion.span key={i} aria-hidden className="pointer-events-none absolute left-1/2 top-1/2 size-24 -translate-x-1/2 -translate-y-1/2 rounded-full border border-primary/40"
              animate={{ scale: over ? [0.6, 2.6] : [0.5, 1.8], opacity: over ? [0.7, 0] : [0.25, 0] }} transition={{ duration: over ? 1.1 : 3, repeat: Infinity, delay: i * (over ? 0.35 : 1), ease: "easeOut" }} />
          ))}
          <span className="relative flex flex-col items-center gap-2">
            <motion.span animate={reduce ? undefined : { y: over ? [0, -8, 0] : [0, -4, 0] }} transition={{ duration: over ? 0.7 : 2.4, repeat: Infinity, ease: "easeInOut" }}
              className="grid size-12 place-items-center rounded-2xl text-white shadow-[0_10px_24px_-8px_color-mix(in_oklab,var(--primary)_80%,transparent)]" style={{ background: GRADIENT }}><UploadCloud className="size-6" aria-hidden /></motion.span>
            <span className="text-sm font-medium">{over ? "Let go to drop" : "Drop files here"}</span>
            <span className="text-xs text-muted-foreground">{hint}</span>
          </span>
        </motion.button>
        <input ref={input} type="file" multiple accept={accept} hidden onChange={(e) => { add(e.target.files); e.target.value = "" }} />
        <p aria-live="polite" className="relative mt-2 min-h-4 text-xs text-red-700 dark:text-red-300">{note}</p>

        {rows.length > 1 && (
          <div className="relative mt-1 h-1.5 overflow-hidden rounded-full bg-muted" role="progressbar" aria-label="Total progress" aria-valuenow={Math.round(total)} aria-valuemin={0} aria-valuemax={100}>
            <motion.div className="h-full rounded-full" style={{ background: GRADIENT }} animate={{ width: `${total}%` }} transition={{ type: "spring", stiffness: 120, damping: 20 }} />
          </div>
        )}

        {/* files fall in and pile up */}
        <Reorder.Group axis="y" values={rows} onReorder={setRows} className="relative mt-3 space-y-2" style={{ transform: "translateZ(10px)" }}>
          <AnimatePresence initial={false}>
            {rows.map((r, i) => {
              const Icon = kindOf(r.file)
              return (
                <Reorder.Item key={r.id} value={r} layout="position"
                  initial={{ opacity: 0, y: reduce ? 0 : -260, rotate: reduce ? 0 : r.tilt * -8, scale: reduce ? 1 : 1.25 }}
                  animate={{ opacity: 1, y: 0, x: reduce ? 0 : r.dx, rotate: reduce ? 0 : r.tilt, scale: 1 }}
                  exit={{ opacity: 0, x: reduce ? 0 : 160, rotate: reduce ? 0 : 12, scale: 0.8, transition: { duration: 0.25 } }}
                  transition={{ ...spring, delay: reduce ? 0 : Math.min(i, 5) * 0.04 }}
                  whileHover={reduce ? undefined : { x: 0, rotate: 0, scale: 1.02, zIndex: 5 }} whileDrag={reduce ? undefined : { scale: 1.06, rotate: 0, zIndex: 20, boxShadow: "0 24px 40px rgba(0,0,0,0.3)" }}
                  className={cn("relative flex cursor-grab list-none items-center gap-3 rounded-xl border bg-background p-3 shadow-[0_6px_16px_-8px_rgba(0,0,0,0.35)] active:cursor-grabbing", r.status === "error" ? "border-red-500/60" : r.status === "done" ? "border-primary/50" : "border-border")}>
                  {r.status === "done" && !reduce && <Burst />}
                  <span className="grid size-10 shrink-0 place-items-center rounded-lg bg-muted text-primary"><Icon className="size-5" aria-hidden /></span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium">{r.file.name}</span>
                    <span className="block text-xs text-muted-foreground">{r.status === "error" ? "Upload failed. Nothing was lost." : r.status === "done" ? `${size(r.file.size)} · uploaded` : `${size(r.file.size)} · uploading`}</span>
                  </span>
                  <Ring value={r.progress} status={r.status} />
                  {r.status === "error" && (
                    <motion.button type="button" onClick={() => start(r)} aria-label={`Retry ${r.file.name}`} initial={{ scale: 0 }} animate={{ scale: 1, rotate: [0, -20, 0] }} className="grid size-11 place-items-center rounded-lg text-primary outline-none hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring"><RotateCw className="size-4" aria-hidden /></motion.button>
                  )}
                  <button type="button" onClick={() => setRows((x) => x.filter((y) => y.id !== r.id))} aria-label={`Remove ${r.file.name}`} className="grid size-11 shrink-0 place-items-center rounded-lg text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"><X className="size-4" aria-hidden /></button>
                </Reorder.Item>
              )
            })}
          </AnimatePresence>
        </Reorder.Group>
      </motion.section>
    </div>
  )
}

export default function Demo() {
  const tried = React.useRef(new Set<string>())
  return (
    <div data-theme="rose" className="fixed inset-0 grid place-items-center overflow-auto bg-background p-6 text-foreground">
      <FileDropPhysics
        onUpload={(file, progress) => new Promise<void>((resolve, reject) => {
          let p = 0
          const broken = file.name.includes("broken") && !tried.current.has(file.name)
          const id = setInterval(() => {
            p += 4 + Math.random() * 9; progress(Math.min(p, 100))
            if (broken && p > 55) { clearInterval(id); tried.current.add(file.name); reject(new Error("network")) }
            else if (p >= 100) { clearInterval(id); resolve() }
          }, 110)
        })}
      />
    </div>
  )
}

